body.push(paraLead("engine.batch \u7684\u4e94\u4e2a\u6027\u8d28\u6784\u6210\u5b89\u5168\u6a21\u578b\uff1a", "\u539f\u5b50\u6027\uff08\u5931\u8d25\u6b65\u9aa4\u4f7f\u6574\u6279\u56de\u6eda\uff09\uff1b\u4e00\u6b65\u64a4\u9500\uff08\u6574\u4e2a\u8fd0\u884c\u5c31\u662f\u4e00\u6b21 edit.undo\uff09\uff1b\u5f15\u7528\uff08$N.key \u8ba9\u540e\u7eed\u6b65\u9aa4\u4f7f\u7528\u524d\u9762\u7684\u7ed3\u679c\uff09\uff1b\u6821\u9a8c\uff08\u6bcf\u4e2a\u547d\u4ee4 id \u4e0e\u53c2\u6570\u5148\u8fc7 command.describe \u4e0e JSON Schema\uff09\uff1b\u6709\u754c\uff08\u4e0d\u8d85\u8fc7 100 \u6b65\u30012MB \u8f7d\u8377\u300160 \u79d2\u8d85\u65f6\uff09\u3002\u547d\u4ee4 id \u4e0e\u53c2\u6570\u4ee5\u771f\u5b9e\u6ce8\u518c\u8868\u4e3a\u51c6\uff08effectcraft.commands() \u4e0e command.describe\uff09\uff0c\u672a\u505a\u5b58\u5728\u6027\u6d4b\u8bd5\u5c31\u786c\u7f16\u7801\u547d\u4ee4 id \u88ab\u660e\u4ee4\u7981\u6b62\u3002\u6a21\u578b\u8ba1\u5212\u7ecf Zod \u7684 EditPlan \u7ea6\u675f\uff08intent \u542b create/edit/animate/style/organize/render/explain/clarify\uff0c\u6458\u8981\u4e0d\u8d85\u8fc7 280 \u5b57\u7b26\uff0c\u98ce\u9669\u4e09\u6863\uff0c\u53d7\u5f71\u54cd\u56fe\u5c42\u4e0d\u8d85\u8fc7 50\uff0c\u6b65\u9aa4 1\u201320 \u4e14\u6bcf\u6b65\u5185\u5d4c\u6279\u6b21\uff09\uff1b\u76ee\u6800\u542b\u7cca\u65f6\u53ef\u8fd4\u56de intent: clarify \u9644\u4e00\u4e2a\u95ee\u9898\uff0c\u80fd\u7528\u5b9a\u5411\u7f16\u8f91\u89e3\u51b3\u5c31\u7edd\u4e0d\u91cd\u65b0\u751f\u6210\u6574\u4e2a\u5408\u6210\u3002"));
