body.push(para("\u4ea4\u4e92\u76ee\u6807\u5199\u5f97\u5f88\u51c6\uff1a\u201c\u52a8\u6548\u65f6\u95f4\u7ebf\u7248\u7684 Cursor\u201d\uff0c\u800c\u4e0d\u662f\u6302\u5728\u7f16\u8f91\u5668\u4e0a\u7684\u804a\u5929\u673a\u5668\u4eba\u3002\u804a\u5929\u5fc5\u987b\u50cf\u4f4f\u5728\u7f16\u8f91\u5668\u91cc\uff0c\u800c\u7f16\u8f91\u5668\u4fdd\u6301 EffectCraft \u51fa\u5382\u539f\u6837\u3002\u786c\u7ea6\u675f\u5305\u62ec\uff1a\u9ed8\u8ba4\u6d6e\u52a8\u3001\u53ef\u9009\u4fa7\u680f\uff08\u4fa7\u680f\u53ea\u6539 iframe \u5bbd\u5ea6\uff0cEffectCraft \u50cf\u4efb\u4f55\u7a97\u53e3 resize \u4e00\u6837\u81ea\u5df1\u91cd\u6392\uff09\uff1b\u9ed8\u8ba4\u4e0d\u906e\u83dc\u5355\u680f\u3001\u65f6\u95f4\u7ebf\u63a7\u5236\u4e0e\u6d3b\u52a8\u9762\u677f\u6807\u7b7e\uff0c\u53ef\u62d6\u52a8\u4f46\u94b3\u5236\u5728\u7f16\u8f91\u5668\u89c6\u53e3\u5185\uff1b\u6240\u6709\u80fd\u529b\u90fd\u5728\u9762\u677f\u5185\uff0c\u4e0d\u5f00\u7b2c\u4e8c\u4e2a\u804a\u5929\u7a97\u53e3\uff1b\u804a\u5929\u5173\u95ed\u65f6\u7f16\u8f91\u5668\u5b8c\u5168\u53ef\u7528\u3002\u5e03\u5c40\u4e09\u6a21\u5f0f\uff1a\u6d6e\u52a8\uff08\u9ed8\u8ba4 420 \u00d7 640\uff0c\u6700\u5c0f 360 \u00d7 480\uff0c\u6700\u5927 720 \u00d7 900 \u6216\u89c6\u53e3\u4e5d\u6210\uff1b\u53f3\u4e0b\u89d2 16px \u8d77\u4f4d\uff1b\u53ef\u62d6\u62fd\u3001\u516b\u65b9\u53ef\u8c03\u3001\u8fb9\u7f18 24px \u5438\u9644\uff1b\u6536\u8d77\u6210 48px \u836f\u4e38\uff09\u3001\u4fa7\u680f\uff08\u9ed8\u8ba4 420px\uff0c\u53ef\u62d6\u5206\u9694\u6761\uff1b\u5c0f\u4e8e 1024px \u65f6\u53d8\u5e95\u90e8\u8868\u5355\uff09\u3001\u836f\u4e38\uff08\u542b\u672a\u8bfb\u6570\u4e0e\u56fe\u6807\uff0c\u70b9\u51fb\u6216 Cmd/Ctrl+L \u6062\u590d\uff09\u3002\u5e03\u5c40\u6309\u7528\u6237\u5b58\u50a8\u5728 localStorage\uff0c\u6062\u590d\u65f6\u94b3\u5236\u5230\u5f53\u524d\u89c6\u53e3\uff0c\u7edd\u4e0d\u6062\u590d\u5230\u5c4f\u5916\u3002"));
