body.push(para("\u5b57\u4f53\u4e09\u4ef6\u5957\uff1aInstrument Serif \u53ea\u505a\u77ed\u6807\u9898\u4e0e\u5927\u6570\u5b57\uff0cInstrument Sans \u627f\u62c5 UI \u4e0e\u6b63\u6587\uff0cJetBrains Mono \u8d1f\u8d23\u65f6\u95f4\u7801\u3001\u4ee3\u7801\u4e0e\u952e\u76d8\u63d0\u793a\uff1b\u5747\u7ecf next/font \u52a0\u8f7d\u5e76\u5c0a\u91cd\u5e03\u5c40\u4e0d\u4f4d\u79fb\u3002\u5b57\u9636\u4ece display-xl\uff0872/0.95\uff0c\u4ec5\u843d\u5730\u9875\u4e3b\u89d2\uff09\u5230 label\uff0812px \u5927\u5199\u3001\u5b57\u8ddd 0.06em\uff09\u5171\u5341\u6863\uff1b\u89c4\u5219\u5305\u62ec\uff1a\u5168\u5927\u5199\u53ea\u7ed9 label \u4e0e\u65f6\u95f4\u7801\uff1b\u7edf\u8ba1\u6570\u5b57\u7528 tabular-nums\uff1b\u6b63\u6587\u4e0d\u8d85\u8fc7 68 \u5b57\u7b26\u5bbd\uff1b\u5e94\u7528\u5185\u4e0d\u5c0f\u4e8e 12px\uff1b\u6697\u5e95\u7981\u7528 300 \u5b57\u91cd\u3002"));
body.push(para("\u7ec4\u4ef6\u5e93\u843d\u5728 packages/ui\uff1aRadix \u65e0\u5934\u539f\u8bed\u52a0 Tailwind \u52a0 CVA\uff0c\u6bcf\u4e2a\u7ec4\u4ef6\u5e26\u793a\u4f8b\u4e0e axe \u6d4b\u8bd5\u3002\u8981\u70b9\uff1a\u6309\u94ae\u4e94\u53d8\u4f53\uff08primary \u4fe1\u53f7\u8272\u586b\u5145\u6df1\u5b57\u3001secondary\u3001ghost\u3001danger\u3001link\uff09\uff0c28\u201344px \u9ad8\uff1b\u8f93\u5165 36px \u9ad8\u3001\u71c3\u70b9 2px \u504f\u79fb 2px\uff1b\u5361\u7247\u9759\u7f6e\u65e0\u9634\u5f71\u3001\u60ac\u505c\u5347\u4e00\u7ea7\u80cc\u666f\u4e0e\u8fb9\u6846\uff1b\u547d\u4ee4\u9762\u677f Cmd/Ctrl+K \u53ea\u5728 SaaS \u58f3\u751f\u6548\uff08\u7f16\u8f91\u5668\u805a\u7126\u65f6\u4e0d\u62a2\u5feb\u6377\u952e\uff09\uff1bcredit \u8868\u5c3a\u4e09\u6001\u9f50\u5907\u4e14\u6c38\u8fdc\u540c\u65f6\u7ed9\u6570\u5b57\uff1b\u9aa8\u67b6\u5c4f\u53ea\u7ed9\u771f\u6b63\u52a0\u8f7d\u4e2d\u7684\u5185\u5bb9\u3002\u9875\u9762\u8bbe\u8ba1\u8986\u76d6\u843d\u5730\u9875\uff08\u4e00\u53e5\u4e3b\u6807\u9898\u52a0\u53cc CTA \u52a0\u771f\u5b9e\u6f14\u793a\uff1b\u8bc1\u660e\u6761\u5199\u4e8b\u5b9e\u800c\u975e\u5047 logo\uff1a\u5173\u952e\u5e27\u30013D\u3001306 \u7279\u6548\u3001\u4ee3\u7406\u7f16\u8f91\u3001\u7248\u672c\u5386\u53f2\uff09\u3001\u8ba4\u8bc1\u9875\uff0855/45 \u5206\u680f\u52a0\u4e00\u5e45\u7535\u5f71\u611f\u9759\u5e27\uff09\u3001\u4e09\u6b65\u5efa\u533a\u3001\u4eea\u8868\u76d8\uff08240px \u53ef\u6536\u5de6\u8f68\u52a0 56px \u9876\u680f\uff09\u3001\u9879\u76ee hub \u4e94\u6807\u7b7e\u3001\u8d26\u5355\u516d\u8282\u3001\u8bbe\u7f6e\u4e5d\u5b50\u9879\u3001\u516c\u5f00\u5206\u4eab\u9875\u4e0e\u7cfb\u7edf\u9875\u3002"));
body.push(paraLead("\u7f16\u8f91\u5668\u9875\u7ea2\u7ebf\uff1a", "\u7f16\u8f91\u5668\u5c31\u662f\u9875\u9762\u672c\u8eab\uff0c\u9ed8\u8ba4\u65e0\u4fa7\u680f\u3001\u65e0\u5e38\u9a7b SaaS \u5bfc\u822a\uff1b\u6d6e\u52a8\u9879\u76ee\u6761\u6307\u9488\u9759\u6b62 2.5 \u79d2\u81ea\u52a8\u9690\u85cf\uff0c\u4e14\u4e0d\u5f97\u76d6\u4f4f\u7f16\u8f91\u5668\u83dc\u5355\u680f\u3002\u7edd\u5bf9\u7981\u6b62\uff1a\u4e0d\u52a0\u538b\u7f29\u7f16\u8f91\u5668\u9ad8\u5ea6\u7684\u5e38\u9a7b\u9876\u5bfc\u822a\uff1b\u4e0d\u5411 iframe \u6ce8\u5165\u4e3b\u9898\u3001CSS \u53d8\u91cf\u6216\u5b57\u4f53\uff1b\u4e0d\u9690\u85cf\u6216\u91cd\u6392 EffectCraft \u9762\u677f\uff1b\u4e0d\u52a0\u7b2c\u4e8c\u6761\u65f6\u95f4\u7ebf\u3001\u5de5\u5177\u680f\u6216\u9884\u89c8\uff1b\u4e0d\u5728\u7f16\u8f91\u5668\u4e0a\u653e\u6a21\u6001\u5bfc\u89c8\uff08\u53ea\u5141\u8bb8\u804a\u5929\u5185\u53ef\u5173\u95ed\u7684\u63d0\u793a\u6807\u8bb0\uff09\u3002\u8d28\u91cf\u95e8\u69db\u8981\u6c42\u7f16\u8f91\u5668\u9875\u622a\u56fe\u4e0e\u4e0a\u6e38\u9010\u50cf\u7d20\u4e00\u81f4\uff0c\u8fd9\u662f\u51bb\u7ed3\u89c4\u5219\u7684\u9a8c\u6536\u5f62\u5f0f\u3002"));
